// Bakes lib/player-headshots.generated.ts: a headshot URL, current team and
// position for each of the twenty players the lesson data is built on.
//
// Why a generated file rather than a runtime fetch: the Question of the Day
// renders on statically-built pages (the question workspace) and hourly
// server pages (the bank, the dashboard, the landing page). A pinned map is
// deterministic, works offline, and costs nothing per render. It changes
// when this script is re-run and at no other time - the same rule the
// lesson data follows (docs/DATA-PIPELINE.md, rule one).
//
// "Current" means the most recent season the player has a stat line in. The
// newest weekly file is tried first, so a player who moved teams shows the
// team he is on now, not the one in the 2022-2024 lesson rows.
//
// The photo URLs point at the NFL's own image CDN, exactly as nflverse
// lists them. components/headshot.tsx hotlinks them as a plain <img> - never
// proxied through our domain - and falls back to an initial on a dead URL.
//
// Usage: node scripts/build-player-headshots.mjs

import { writeFile } from "node:fs/promises";
import path from "node:path";
import { parse } from "csv-parse/sync";
import { loadTs } from "./load-ts.mjs";

const BASE =
  "https://github.com/nflverse/nflverse-data/releases/download/stats_player";

// Newest first. A season with no file yet (before kickoff) 404s and is
// skipped; the next one down fills in.
const SEASONS = [2026, 2025, 2024];

const root = process.cwd();
const data = await loadTs(path.join(root, "lib/fantasy-data.ts"), root);
const wanted = new Set(data.PLAYERS);

/** name -> { url, team, position, season } for the newest season seen. */
const found = new Map();

for (const season of SEASONS) {
  if (found.size === wanted.size) break;
  const url = `${BASE}/stats_player_week_${season}.csv`;
  process.stdout.write(`${season}: `);
  const res = await fetch(url);
  if (!res.ok) {
    console.log(`no file (${res.status}), skipping`);
    continue;
  }
  const rows = parse(await res.text(), {
    columns: true,
    skip_empty_lines: true,
    relax_column_count: true,
  });
  let added = 0;
  // Iterate newest week first so the team is the latest one that season.
  rows.sort((a, b) => Number(b.week) - Number(a.week));
  for (const r of rows) {
    const name = (r.player_display_name ?? "").trim();
    if (!wanted.has(name) || found.has(name)) continue;
    const shot = (r.headshot_url ?? "").trim();
    if (!shot.startsWith("https://")) continue;
    found.set(name, {
      url: shot,
      team: (r.team ?? "").trim(),
      position: (r.position ?? "").trim(),
      season,
    });
    added++;
  }
  console.log(`${added} players`);
}

const missing = [...wanted].filter((n) => !found.has(n));
if (missing.length) {
  // Not fatal: the component falls back to an initial. But say so loudly,
  // because a missing face on the day's question is the kind of thing that
  // gets noticed.
  console.warn(`WARNING - no headshot found for: ${missing.join(", ")}`);
}

const entries = [...found.entries()].sort(([a], [b]) => a.localeCompare(b));

const out = `// GENERATED by scripts/build-player-headshots.mjs - do not edit by hand.
//
// Headshot URL, current team and position for each lesson player, from
// nflverse-data's weekly stats release. The URLs are the NFL's own image CDN
// exactly as nflverse lists them; components/headshot.tsx hotlinks them and
// never proxies them. "Current" is the newest season with a stat line.
//
// Source and licence: lib/data-source.ts

export type PlayerHeadshot = {
  url: string;
  /** Team in the newest season seen, which may differ from the lesson rows. */
  team: string;
  position: string;
  season: number;
};

export const PLAYER_HEADSHOTS: Record<string, PlayerHeadshot> = {
${entries.map(([name, v]) => `  ${JSON.stringify(name)}: ${JSON.stringify(v)},`).join("\n")}
};
`;

await writeFile("lib/player-headshots.generated.ts", out, "utf8");
console.log(
  `lib/player-headshots.generated.ts - ${found.size}/${wanted.size} players`,
);
